import { useId } from "react";

/**
 * Logo MarketDash como SVG INLINE (não como <img>/asset).
 * Motivo: SVG inlinado pelo Vite vira data-URI e o `url(#gradiente)` quebra no <img>
 * (renderiza quadrado branco). Inline no DOM renderiza sempre e o gradiente funciona.
 * O id do gradiente é único por instância (useId) para não colidir com outras cópias.
 */

type Props = { className?: string; title?: string };

function SymbolDefsAndShapes({ gid }: { gid: string }) {
  return (
    <>
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor="#1c3c5e" />
          <stop offset="1" stopColor="#0d1726" />
        </linearGradient>
      </defs>
      <rect x="0" y="0" width="48" height="48" rx="13" fill={`url(#${gid})`} stroke="rgba(124,184,242,.25)" />
      <rect x="13" y="28" width="5" height="9" rx="1.4" fill="#7CB8F2" opacity=".55" />
      <rect x="21.5" y="23" width="5" height="14" rx="1.4" fill="#7CB8F2" opacity=".75" />
      <rect x="30" y="18" width="5" height="19" rx="1.4" fill="#7CB8F2" opacity=".95" />
      <path d="M11 32 C19 31, 25 27, 36 15" fill="none" stroke="#fff" strokeWidth="3" strokeLinecap="round" />
      <path
        d="M36 15 L29.5 15.2 M36 15 L36.2 21.6"
        fill="none"
        stroke="#fff"
        strokeWidth="3"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </>
  );
}

/** Só o símbolo (quadrado). Para favicon, sidebar colapsada, avatar. */
export function BrandSymbol({ className, title = "MarketDash" }: Props) {
  const gid = useId();
  return (
    <svg viewBox="0 0 48 48" className={className} role="img" aria-label={title} xmlns="http://www.w3.org/2000/svg">
      <SymbolDefsAndShapes gid={gid} />
    </svg>
  );
}

